"use client"
import { useMemo, useState } from "react"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { RECENT_RECIPIENTS } from "../data"
import { RecipientRow } from "./_parts"
import type { SendMoneyStepProps } from "../schema"

export function Recipient({ data, patch, next }: SendMoneyStepProps) {
  const [query, setQuery] = useState("")

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return RECENT_RECIPIENTS
    return RECENT_RECIPIENTS.filter((r) => r.name.toLowerCase().includes(q))
  }, [query])

  const select = (id: string) => {
    const recipient = RECENT_RECIPIENTS.find((r) => r.id === id) ?? null
    patch({ recipient })
    next()
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)", paddingInline: "var(--atlas-spacing-4)" }}>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <Label htmlFor="recipient-search">Search recipients</Label>
        <Input
          id="recipient-search"
          type="search"
          variant="default"
          placeholder="Search by name"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <span
          style={{
            fontSize: "var(--atlas-text-caption)",
            fontWeight: "var(--atlas-font-weight-medium)",
            color: "var(--atlas-foreground-muted)",
          }}
        >
          Recent recipients
        </span>
        <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
          {filtered.map((recipient) => (
            <RecipientRow
              key={recipient.id}
              recipient={recipient}
              selected={data.recipient?.id === recipient.id}
              onSelect={() => select(recipient.id)}
            />
          ))}
          {filtered.length === 0 && (
            <p style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>
              No recipients match “{query}”.
            </p>
          )}
        </div>
      </div>
    </div>
  )
}

